<?php
header('Content-Type: application/json');

// Fungsi untuk ambil data dari API
function getSalesData($startDate, $endDate) {
    $curl = curl_init();

    curl_setopt_array($curl, array(
        CURLOPT_URL => "https://mcp.matahari.co.id:81/OpenReport/Sales?startDate=$startDate&endDate=$endDate",
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HTTPHEADER => array(
            'Accept: text/plain',
            'Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..Z7nAbS62jDDBLMuMUHDz7sW45KxAT7Z92j7BoAzI24k' // Ganti token dengan token valid
        ),
    ));

    $response = curl_exec($curl);
    $error = curl_error($curl);
    curl_close($curl);

    if ($error) {
        return ['result' => [], 'error' => $error];
    }

    $decoded = json_decode($response, true);
    return $decoded ?? ['result' => []];
}

// Validasi parameter
if (isset($_GET['startDate']) && isset($_GET['endDate'])) {
    $startDate = $_GET['startDate'];
    $endDate = $_GET['endDate'];

    $data = getSalesData($startDate, $endDate);
    echo json_encode($data);
} else {
    echo json_encode(['result' => [], 'error' => 'Parameter startDate dan endDate diperlukan.']);
}
